mapper.select:
select
from meattrade_pratique_register p left join meattrade_pork_arrange_audit paat on p.id = paat.pratique_register_id left join meattrade_pork_arrange pae on paat.pork_arrange_id = pae.id
and p.pork_report_id in
#{porkReportId}
and p.pratique_tickets != ceiling(pae.slices / 2) and p.tenant = #{tenant}
order by p.pork_report_code

select
from meattrade_pratique_register p left join meattrade_pork_arrange_audit paat on p.id = paat.pratique_register_id left join meattrade_pork_arrange pae on paat.pork_arrange_id = pae.id
and p.pork_report_id in
#{porkReportId}
and p.pratique_tickets != ceiling(pae.slices / 2) and p.tenant = #{tenant}
order by p.pork_report_code

select

from meattrade_pratique_register p
left join meattrade_pork_report pr
on p.pork_report_id = pr.id


        and p.pork_report_code like concat("%",#{param.keyword},"%")


        or pr.supplier_id in

            #{supplierId}



        and p.status = #{param.status}


and p.tenant = #{param.tenant}
order by p.pork_report_code

SELECT t1.id, t2.supplier_id, t1.pork_report_id, t1.pork_report_code, t2.goods_category_id, t2.goods_category_name, t2.fresh_label, t2.report_slices as pork_report_slices, t1.registrant_id, t1.pratique_slices, t1.pratique_tickets, t1.pratique_code, t1.remark, t1.`status`, t1.register_time FROM `meattrade_pratique_register` t1 INNER JOIN meattrade_pork_report t2 on t1.pork_report_id = t2.id
t1.tenant = #{param.tenant}
and (t1.pork_report_code like concat('%',#{param.keyword},'%')
or t2.supplier_id in
#{supplierId}
)
and t1.status = #{param.status}
and t1.id in
#{id}
and t1.pork_report_id in
#{porkReportId}
and t1.register_time >= #{param.period.begin}
and t1.register_time <= #{param.period.end}
order by t1.pork_report_code desc
